(function(){
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const url=s=>/^(https:\/\/[^\s]+|\/[a-z0-9][^\s]*|#[^\s]+)$/i.test(s||'')?s:'';
 function create(api){
  let settings={enabled:false,interval:5,slides:[],promos:[],categories:[]},products=[],timer=null,draft=null,paused=false,index=0;
  const picture=(item,cls='')=>`<picture>${url(item.mobile_url)?`<source media="(max-width:620px)" srcset="${esc(url(item.mobile_url))}">`:''}<img class="${cls}" src="${esc(url(item.image_url))}" alt="${esc(item.title||'Marketplace collection')}" loading="lazy"></picture>`;
  const media=item=>url(item.link)?`<a href="${esc(url(item.link))}">${picture(item)}</a>`:picture(item);
  function show(i){const host=document.getElementById('carouselPartTwo');if(!host)return;const slides=[...host.querySelectorAll('.secondary-slide')];if(!slides.length)return;index=(i+slides.length)%slides.length;slides.forEach((s,n)=>{s.hidden=n!==index;s.setAttribute('aria-hidden',String(n!==index))});}
  function render(){
   const anchor=document.getElementById('featured')?.closest('.section');if(!anchor)return;
   let root=document.getElementById('premiumDiscovery');if(!root){anchor.insertAdjacentHTML('afterend','<div id="premiumDiscovery" class="shop-home-section"></div>');root=document.getElementById('premiumDiscovery');}
   root.classList.toggle('hidden',!!document.querySelector('[data-shop-view="vendors"].active,[data-shop-view="categories"].active'));
   const slides=settings.enabled?(settings.slides||[]).filter(x=>x.enabled&&url(x.image_url)):[],promos=(settings.promos||[]).filter(x=>x.enabled&&url(x.image_url));
   const vendors=[...new Map(products.map(p=>[p.vendor_id,{id:p.vendor_id,...p.vendors}])).values()];
   root.innerHTML=`${slides.length?`<section id="carouselPartTwo" class="secondary-carousel" aria-label="Marketplace collections carousel">${slides.map((item,i)=>`<div class="secondary-slide" ${i?'hidden':''}>${media(item)}</div>`).join('')}${slides.length>1?`<button class="carousel-pause" type="button" aria-label="${paused?'Resume':'Pause'} collection carousel" aria-pressed="${paused}">${paused?'▶':'Ⅱ'}</button>`:''}</section>`:''}${promos.length?`<section class="premium-promos" aria-label="Featured collections">${promos.map(item=>`<div>${media(item)}</div>`).join('')}</section>`:''}${vendors.length?`<section class="premium-vendors section"><header><div><span class="eyebrow">SHOP BY SELLER</span><h2>Discover vendors</h2></div><button type="button" class="text-button" data-shop-view="vendors">View all →</button></header><div class="premium-vendor-row">${vendors.map(v=>`<button type="button" data-directory-vendor="${esc(v.id)}">${url(v.logo_url)?`<img src="${esc(v.logo_url)}" alt="" loading="lazy">`:`<span class="premium-vendor-initial">${esc((v.business_name||'Store').slice(0,2))}</span>`}<span><strong>${esc(v.business_name||'Store')}</strong><small>Visit store →</small></span></button>`).join('')}</div></section>`:''}`;
   clearInterval(timer);index=0;const pause=root.querySelector('.carousel-pause');if(pause)pause.onclick=()=>{paused=!paused;pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',(paused?'Resume':'Pause')+' collection carousel');pause.setAttribute('aria-pressed',String(paused))};
   if(slides.length>1&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>{if(!paused&&!document.hidden&&!root.classList.contains('hidden')&&document.getElementById('page-shop')?.classList.contains('active')&&!root.contains(document.activeElement)&&!root.matches(':hover'))show(index+1)},Math.max(3,Number(settings.interval)||5)*1000);
   applyCategoryImages();
  }
  function applyCategoryImages(){document.querySelectorAll('[data-pick-category],.featured-category-card,[data-directory-category].category-directory-card').forEach(card=>{const name=card.dataset.pickCategory||card.dataset.directoryCategory;const custom=(settings.categories||[]).find(c=>c.name===name&&c.enabled),product=products.find(p=>p.category===name&&url(p.image_url)),image=card.querySelector('img');if(image){const src=url(custom?.image_url)||url(product?.image_url);if(src){image.src=src;image.alt=name;image.classList.add('collection-photo');}}});}
  async function load(items){products=items;const r=await api.db.rpc('marketplace_presentation_settings');if(!r.error&&r.data){settings=r.data;}render();}
  async function upload(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5242880)throw Error('Choose JPG, PNG or WebP up to 5 MB');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=`notices/marketplace-${crypto.randomUUID()}.${ext}`;const r=await api.db.storage.from('site-announcements').upload(path,file,{contentType:file.type,upsert:false});if(r.error)throw r.error;return api.db.storage.from('site-announcements').getPublicUrl(path).data.publicUrl;}
  async function mountAdmin(){
   if(document.getElementById('premiumAdmin'))return;const hero=document.getElementById('heroBannerForm')?.closest('.card');if(!hero)return;
   const response=await api.db.rpc('marketplace_presentation_settings');if(response.error)throw response.error;settings=response.data||settings;draft=JSON.parse(JSON.stringify(settings));
   hero.insertAdjacentHTML('afterend','<section id="premiumAdmin" class="card premium-editor"></section>');renderAdmin();
  }
  function renderAdmin(){const host=document.getElementById('premiumAdmin');if(!host)return;
   const labels={slides:'Carousel Part Two',promos:'Promotional image tiles',categories:'Collection images'},limits={slides:8,promos:2,categories:60};
   host.innerHTML='<div class="card-head"><div><h2>Premium marketplace</h2><p>Manage the short carousel, promotional images and collection artwork.</p></div></div><div class="card-body"><div class="premium-editor-settings"><label><input type="checkbox" id="secondCarouselEnabled" '+(draft.enabled?'checked':'')+'> Show Carousel Part Two</label><label>Rotation (seconds)<input type="number" id="secondCarouselInterval" min="3" max="15" value="'+draft.interval+'"></label></div>'+Object.keys(labels).map(kind=>`<section class="premium-editor-group" data-kind="${kind}"><header><h3>${labels[kind]}</h3><button type="button" class="btn small" data-promo-add="${kind}" ${draft[kind].length>=limits[kind]?'disabled':''}>Add image</button></header><div class="premium-admin-table"><table><thead><tr><th>Preview</th><th>${kind==='categories'?'Category':'Image description'}</th><th>Status</th><th>Actions</th></tr></thead><tbody>${draft[kind].map((item,i)=>`<tr><td>${url(item.image_url)?`<img src="${esc(url(item.image_url))}" alt="Preview">`:'No image'}</td><td>${esc(kind==='categories'?item.name||'Choose category':item.title||'Untitled image')}</td><td>${item.enabled?'Active':'Hidden'}</td><td><button type="button" class="btn small" data-promo-edit="${kind}:${i}">Edit</button><button type="button" class="btn small" data-promo-up="${kind}:${i}" ${!i?'disabled':''}>↑</button><button type="button" class="btn small" data-promo-remove="${kind}:${i}">Remove</button></td></tr><tr id="premium-edit-${kind}-${i}" hidden><td colspan="4"><div class="premium-image-fields" data-kind="${kind}" data-index="${i}">${kind==='categories'?`<label>Category<select data-field="name"><option value="">Choose category</option>${api.categories().map(c=>`<option ${c===item.name?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}<label>Image description<input data-field="title" maxlength="120" value="${esc(item.title)}"></label><label>Desktop image<input type="file" data-upload="image_url" accept="image/jpeg,image/png,image/webp"><input aria-label="Desktop image URL" data-field="image_url" value="${esc(item.image_url)}" placeholder="HTTPS image URL or /assets/image.webp"></label>${kind!=='categories'?`<label>Mobile image (optional)<input type="file" data-upload="mobile_url" accept="image/jpeg,image/png,image/webp"><input aria-label="Mobile image URL" data-field="mobile_url" value="${esc(item.mobile_url||'')}"></label><label>Destination link<input data-field="link" value="${esc(item.link||'')}" placeholder="#product/… or https://…"></label>`:''}<label><input type="checkbox" data-field="enabled" ${item.enabled?'checked':''}> Show image</label></div></td></tr>`).join('')||'<tr><td colspan="4">No images. Add an image to begin.</td></tr>'}</tbody></table></div></section>`).join('')+'<button type="button" class="btn primary" id="savePremiumPresentation">Save marketplace layout</button><p role="status" id="premiumSaveStatus">Changes remain drafts until saved. JPG, PNG or WebP, up to 5 MB each.</p></div>';
   host.querySelector('#secondCarouselEnabled').onchange=e=>draft.enabled=e.target.checked;host.querySelector('#secondCarouselInterval').oninput=e=>draft.interval=Number(e.target.value);
   host.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{const box=input.closest('[data-index]');draft[box.dataset.kind][Number(box.dataset.index)][input.dataset.field]=input.type==='checkbox'?input.checked:input.value;});
   host.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const status=host.querySelector('#premiumSaveStatus'),save=host.querySelector('#savePremiumPresentation');save.disabled=true;status.textContent='Uploading image…';try{const image=await upload(file),box=input.closest('[data-index]');draft[box.dataset.kind][Number(box.dataset.index)][input.dataset.upload]=image;box.querySelector(`[data-field="${input.dataset.upload}"]`).value=image;status.textContent='Image uploaded. Save marketplace layout to publish.';}catch(err){status.textContent=err.message;}finally{save.disabled=false;}});
   host.querySelectorAll('[data-promo-add]').forEach(b=>b.onclick=()=>{const kind=b.dataset.promoAdd;draft[kind].push({title:'',name:'',image_url:'',mobile_url:'',link:'',enabled:true});renderAdmin();document.getElementById(`premium-edit-${kind}-${draft[kind].length-1}`).hidden=false;});
   for(const action of ['edit','up','remove'])host.querySelectorAll(`[data-promo-${action}]`).forEach(b=>b.onclick=()=>{const [kind,position]=b.getAttribute('data-promo-'+action).split(':'),i=Number(position);if(action==='edit'){const row=document.getElementById(`premium-edit-${kind}-${i}`);row.hidden=!row.hidden;return;}if(action==='remove')draft[kind].splice(i,1);else if(i>0)[draft[kind][i-1],draft[kind][i]]=[draft[kind][i],draft[kind][i-1]];renderAdmin();});
   host.querySelector('#savePremiumPresentation').onclick=async e=>{const button=e.currentTarget,status=host.querySelector('#premiumSaveStatus');button.disabled=true;status.textContent='Saving…';try{const r=await api.db.rpc('admin_save_marketplace_presentation',{p_settings:draft});if(r.error)throw r.error;settings=JSON.parse(JSON.stringify(r.data));render();status.textContent='Saved. The marketplace is updated.';}catch(err){status.textContent=err.message||'Could not save';}finally{button.disabled=false;}};
  }
  return {load,render,mountAdmin,applyCategoryImages};
 }
 window.MioPremium={create};
})();
